const now = new Date();

const parts = new Intl.DateTimeFormat('en-US', {
  timeZone: 'America/Merida',
  weekday: 'short',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  hour12: false
}).formatToParts(now);

const get = (type) => parts.find(p => p.type === type)?.value ?? null;

const weekday = get('weekday');
const hour = Number(get('hour'));
const minute = Number(get('minute'));
const isWeekday = ['Mon','Tue','Wed','Thu','Fri'].includes(weekday);

const dateParts = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'America/Merida',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).formatToParts(now);

const y = dateParts.find(p => p.type === 'year')?.value;
const m = dateParts.find(p => p.type === 'month')?.value;
const d = dateParts.find(p => p.type === 'day')?.value;
const eodDate = `${y}-${m}-${d}`;

// Appointment sync window:
// 60 days backwards catches late Show / No Show status updates.
// 120 days forward keeps upcoming School Tours visible.
const appointmentsStartMs = now.getTime() - (60 * 24 * 60 * 60 * 1000);
const appointmentsEndMs = now.getTime() + (120 * 24 * 60 * 60 * 1000);

// Calls are re-read for 60 days because GHL may populate duration/status
// after the initial message record. With current Milhano volume this remains
// comfortably under the API's 1000-record page limit.
const callsStartDate = new Date(now.getTime() - (60 * 24 * 60 * 60 * 1000)).toISOString();
const callsEndDate = now.toISOString();

return [{
  json: {
    location_id: 'ZzRtp9n8n76ARy99VzJc',
    run_started_at: now.toISOString(),
    eod_date: eodDate,
    local_weekday: weekday,
    local_hour: hour,
    local_minute: minute,
    should_refresh_eod:
      isWeekday &&
      hour === 14 &&
      minute >= 50 &&
      minute <= 59,

    // Pasadía is pinned by Calendar ID. Keywords remain as a safe fallback
    // for School Tour and any future admissions calendar aliases.
    appointment_calendar_ids: ['a0bvCaXgCdVwSrgPELza'],
    pasadia_calendar_id: 'a0bvCaXgCdVwSrgPELza',
    appointment_calendar_keywords: [
      'school tour',
      'tour escolar',
      'visita escolar',
      'visita',
      'pasadia',
      'pasadía',
      'trial day'
    ],
    appointments_start_ms: appointmentsStartMs,
    appointments_end_ms: appointmentsEndMs,
    calls_start_date: callsStartDate,
    calls_end_date: callsEndDate
  }
}];

const responseItems = $input.all();
const config = $('Config | Orchestrator').first().json;

function clean(value) {
  if (value === null || value === undefined) return null;
  const text = String(value).trim();
  return text.length ? text : null;
}

function toIso(value) {
  if (value === null || value === undefined || value === '') return null;
  let normalized = value;
  if (typeof normalized === 'number' && normalized < 100000000000) normalized *= 1000;
  const date = new Date(normalized);
  return Number.isNaN(date.getTime()) ? null : date.toISOString();
}

function fnv1a(text) {
  let hash = 0x811c9dc5;
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193);
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
}

function extractMessages(payload) {
  if (!payload) return [];
  if (Array.isArray(payload)) return payload.flatMap(extractMessages);
  if (Array.isArray(payload.messages)) return payload.messages;
  if (Array.isArray(payload.data?.messages)) return payload.data.messages;
  if (Array.isArray(payload.body?.messages)) return payload.body.messages;
  if (Array.isArray(payload.data)) return payload.data;
  return [];
}

const rawMessages = responseItems.flatMap((item) => extractMessages(item.json));
const deduped = new Map();

for (const message of rawMessages) {
  const messageId = clean(
    message.id ?? message._id ?? message.messageId ?? message.message_id
  );
  if (!messageId) continue;

  const messageType = clean(
    message.messageType ?? message.channel ?? message.type
  );

  const isWhatsApp =
    String(messageType ?? '').toLowerCase().includes('whatsapp') ||
    Number(message.type) === 19;

  if (!isWhatsApp) continue;

  const direction = clean(
    message.direction ?? message.messageDirection ?? message.message_direction
  )?.toLowerCase();

  if (!['inbound', 'outbound'].includes(direction)) continue;

  const userId = clean(
    message.userId ?? message.user_id ?? message.senderId ?? message.sender?.id
  );

  const messageSource = clean(
    message.source ?? message.provider ?? message.origin
  )?.toLowerCase() ?? 'unknown';

  const workflowId = clean(
    message.workflowId ??
    message.workflow_id ??
    message.automationId ??
    message.automation_id
  );

  const isAutomated =
    messageSource === 'workflow' ||
    Boolean(workflowId) ||
    message.isAutomated === true ||
    message.is_automated === true;

  let origin;
  if (isAutomated) {
    origin = 'ghl_workflow';
  } else if (direction === 'inbound') {
    origin = 'external_contact';
  } else if (messageSource === 'app' && !userId) {
    origin = 'shared_whatsapp_app';
  } else if (userId) {
    origin = 'ghl_identified_user';
  } else {
    origin = 'unknown';
  }

  const body = clean(
    message.body ?? message.message ?? message.text ?? message.content
  ) ?? '';

  const attachments = Array.isArray(message.attachments)
    ? message.attachments
    : [];

  const eventTimestamp =
    toIso(
      message.dateAdded ??
      message.createdAt ??
      message.created_at ??
      message.timestamp ??
      message.sentAt
    ) ?? config.run_started_at;

  const deliveryStatus = clean(
    message.status ?? message.deliveryStatus ?? message.delivery_status
  )?.toLowerCase() ?? 'unknown';

  deduped.set(messageId, {
    message_id: messageId,
    contact_id: clean(
      message.contactId ?? message.contact_id ?? message.contact?.id
    ),
    conversation_id: clean(
      message.conversationId ?? message.conversation_id
    ),
    user_id: userId,
    direction,
    delivery_status: deliveryStatus,
    event_timestamp: eventTimestamp,
    origin,
    message_source: messageSource,
    is_automated: isAutomated,
    message_body_hash: fnv1a(body),
    has_attachment: attachments.length > 0,
    attachment_count: attachments.length,
    body_length: body.length,
    from_number: clean(message.from),
    to_number: clean(message.to),
    content_type: clean(message.contentType),
    alt_id: clean(message.altId),
    workflow_id: workflowId
  });
}

const normalizedMessages = [...deduped.values()];

return [{
  json: {
    p_location_id: config.location_id,
    p_messages: normalizedMessages,
    p_reconciled_at: new Date().toISOString(),
    raw_records_received: rawMessages.length,
    unique_whatsapp_messages: normalizedMessages.length,
    inbound_messages: normalizedMessages.filter(m => m.direction === 'inbound').length,
    outbound_messages: normalizedMessages.filter(m => m.direction === 'outbound').length,
    manual_outbound_candidates: normalizedMessages.filter(
      m =>
        m.direction === 'outbound' &&
        m.message_source === 'app' &&
        !m.is_automated &&
        ['sent', 'delivered', 'read'].includes(m.delivery_status)
    ).length,
    automated_outbound_candidates: normalizedMessages.filter(
      m => m.direction === 'outbound' && m.is_automated
    ).length
  }
}];

const responseItems = $input.all();
const config = $('Config | Orchestrator').first().json;

function clean(value) {
  if (value === null || value === undefined) return null;
  const text = String(value).trim();
  return text.length ? text : null;
}

function toIso(value) {
  if (value === null || value === undefined || value === '') return null;
  let normalized = value;
  if (typeof normalized === 'number' && normalized < 100000000000) normalized *= 1000;
  const date = new Date(normalized);
  return Number.isNaN(date.getTime()) ? null : date.toISOString();
}

function durationSeconds(value) {
  if (value === null || value === undefined || value === '') return 0;
  if (typeof value === 'number' && Number.isFinite(value)) {
    return Math.max(0, Math.round(value));
  }

  const text = String(value).trim();
  if (/^\d+(\.\d+)?$/.test(text)) return Math.max(0, Math.round(Number(text)));

  const parts = text.split(':').map(Number);
  if (parts.some(Number.isNaN)) return 0;

  if (parts.length === 3) {
    return Math.max(0, Math.round(parts[0] * 3600 + parts[1] * 60 + parts[2]));
  }
  if (parts.length === 2) {
    return Math.max(0, Math.round(parts[0] * 60 + parts[1]));
  }
  return 0;
}

function extractMessages(payload) {
  if (!payload) return [];
  if (Array.isArray(payload)) return payload.flatMap(extractMessages);
  if (Array.isArray(payload.messages)) return payload.messages;
  if (Array.isArray(payload.data?.messages)) return payload.data.messages;
  if (Array.isArray(payload.body?.messages)) return payload.body.messages;
  if (Array.isArray(payload.data)) return payload.data;
  return [];
}

const rawMessages = responseItems.flatMap((item) => extractMessages(item.json));
const deduped = new Map();

for (const message of rawMessages) {
  const messageId = clean(
    message.id ?? message.messageId ?? message.message_id ?? message._id
  );
  if (!messageId) continue;

  const messageType = clean(
    message.messageType ?? message.messageTypeString ?? message.type
  );

  const rawCallStatus = clean(
    message.callStatus ??
    message.call_status ??
    message.meta?.callStatus ??
    message.meta?.call_status
  );

  const rawDuration =
    message.callDuration ??
    message.call_duration ??
    message.meta?.callDuration ??
    message.meta?.call_duration;

  const looksLikeCall =
    String(messageType ?? '').toLowerCase().includes('call') ||
    String(messageType ?? '').toLowerCase().includes('voicemail') ||
    rawCallStatus !== null ||
    (rawDuration !== null && rawDuration !== undefined);

  if (!looksLikeCall) continue;

  const direction = clean(
    message.direction ?? message.messageDirection ?? message.message_direction
  )?.toLowerCase();

  if (!['inbound', 'outbound'].includes(direction)) continue;

  const deliveryStatus = clean(
    message.status ?? message.deliveryStatus ?? message.delivery_status
  )?.toLowerCase() ?? 'unknown';

  const callStatus = (rawCallStatus ?? deliveryStatus)?.toLowerCase();

  const disposition = clean(
    message.callDisposition ??
    message.call_disposition ??
    message.disposition ??
    message.meta?.callDisposition ??
    message.meta?.call_disposition ??
    message.meta?.disposition
  );

  const duration = durationSeconds(rawDuration);

  deduped.set(messageId, {
    message_id: messageId,
    contact_id: clean(
      message.contactId ?? message.contact_id ?? message.contact?.id
    ),
    conversation_id: clean(
      message.conversationId ?? message.conversation_id
    ),
    user_id: clean(
      message.userId ??
      message.user_id ??
      message.answeredBy ??
      message.answered_by
    ),
    direction,
    delivery_status: deliveryStatus,
    call_status: callStatus,
    call_duration_seconds: duration,
    call_disposition: disposition,
    event_timestamp:
      toIso(
        message.dateAdded ??
        message.createdAt ??
        message.created_at ??
        message.timestamp
      ) ?? config.run_started_at,
    message_source: clean(
      message.source ?? message.provider ?? message.origin
    )?.toLowerCase() ?? 'unknown',
    from_number: clean(message.from),
    to_number: clean(message.to),
    has_recording:
      Array.isArray(message.attachments) &&
      message.attachments.length > 0,
    message_type: messageType
  });
}

const calls = [...deduped.values()];
const isRawConnected = call =>
  ['completed', 'answered'].includes(call.call_status);
const isTwoMinutesPlus = call =>
  ['completed', 'answered'].includes(call.call_status) &&
  call.call_duration_seconds >= 120;

return [{
  json: {
    p_location_id: config.location_id,
    p_messages: calls,
    p_reconciled_at: new Date().toISOString(),
    raw_records_received: rawMessages.length,
    unique_calls: calls.length,
    outbound_attempts: calls.filter(c => c.direction === 'outbound').length,
    inbound_calls: calls.filter(c => c.direction === 'inbound').length,
    raw_connected_calls: calls.filter(isRawConnected).length,
    calls_with_duration: calls.filter(c => c.call_duration_seconds > 0).length,
    calls_2min_plus: calls.filter(isTwoMinutesPlus).length,
    max_call_duration_seconds: calls.reduce(
      (max, c) => Math.max(max, c.call_duration_seconds || 0),
      0
    )
  }
}];

const cfg = $('Config | Orchestrator').first().json;
const wa = $('Normalize | WhatsApp Batch').first().json;
const calls = $('Normalize | Call Batch').first().json;
const appointments = $('Normalize | Appointment Batch').first().json;

function nodeResult(name) {
  try {
    return $(name).first().json;
  } catch {
    return null;
  }
}

const waDb = nodeResult('Supabase | Reconcile WhatsApp Batch');
const callDb = nodeResult('Supabase | Reconcile Call Batch');
const appointmentDb = nodeResult('Supabase | Reconcile Appointments');
const health = nodeResult('Supabase | Refresh System Health');
const eod = nodeResult('Supabase | Refresh All EOD');

return [{
  json: {
    ok: true,
    workflow: 'MILHANO | 09 | Dashboard Refresh Orchestrator v4 | Admissions V2',
    started_at: cfg.run_started_at,
    finished_at: new Date().toISOString(),
    eod_date: cfg.eod_date,
    eod_refreshed: Boolean(cfg.should_refresh_eod),

    whatsapp: {
      raw_records_received: wa.raw_records_received,
      unique_messages: wa.unique_whatsapp_messages,
      inbound: wa.inbound_messages,
      outbound: wa.outbound_messages,
      db_response: waDb
    },

    calls: {
      raw_records_received: calls.raw_records_received,
      unique_calls: calls.unique_calls,
      outbound_attempts: calls.outbound_attempts,
      inbound_calls: calls.inbound_calls,
      connected_calls: calls.raw_connected_calls,
      calls_with_duration: calls.calls_with_duration,
      calls_2min_plus: calls.calls_2min_plus,
      max_call_duration_seconds: calls.max_call_duration_seconds,
      db_response: callDb
    },

    appointments: {
      selected_calendars: appointments.selected_calendars,
      raw_events_received: appointments.raw_events_received,
      classified_appointments: appointments.classified_appointments,
      school_tour_appointments: appointments.school_tour_appointments,
      trial_day_appointments: appointments.trial_day_appointments,
      db_response: appointmentDb
    },

    health_response: health,
    eod_response: eod
  }
}];

const config = $('Config | Orchestrator').first().json;
const payloads = $input.all().map(item => item.json);

function clean(value) {
  if (value === null || value === undefined) return '';
  return String(value).trim();
}

function extractCalendars(payload) {
  if (!payload) return [];
  if (Array.isArray(payload)) return payload.flatMap(extractCalendars);
  if (Array.isArray(payload.calendars)) return payload.calendars;
  if (Array.isArray(payload.data?.calendars)) return payload.data.calendars;
  if (Array.isArray(payload.data)) return payload.data;
  return [];
}

const calendars = payloads.flatMap(extractCalendars);
const exactIds = new Set((config.appointment_calendar_ids ?? []).map(String));
const keywords = (config.appointment_calendar_keywords ?? [])
  .map(v => clean(v).toLocaleLowerCase('es'))
  .filter(Boolean);

const active = calendars.filter(calendar => calendar.isActive !== false);

const normalized = active.map(calendar => {
  const id = clean(calendar.id ?? calendar.calendarId);
  const name = clean(
    calendar.name ??
    calendar.calendarName ??
    calendar.title ??
    calendar.slug
  ) || id;

  const haystack = [
    name,
    clean(calendar.description),
    clean(calendar.slug)
  ].join(' ').toLocaleLowerCase('es');

  const exactMatch = exactIds.has(id);
  const keywordMatch = keywords.some(keyword => haystack.includes(keyword));

  return {
    calendar_id: id,
    calendar_name: name,
    exact_match: exactMatch,
    keyword_match: keywordMatch,
  };
}).filter(row => row.calendar_id);

let selected = normalized.filter(row => row.exact_match || row.keyword_match);
let selectionMode = 'configured_match';

// Safe fallback: if calendar naming does not match our keywords, query all
// active calendars. Appointment normalization still discards unrelated events.
if (!selected.length) {
  selected = normalized;
  selectionMode = 'fallback_all_active';
}

if (!selected.length) {
  throw new Error('GHL returned no active calendars for the Milhano location.');
}

return selected.map(row => ({
  json: {
    ...row,
    selection_mode: selectionMode,
    appointments_start_ms: config.appointments_start_ms,
    appointments_end_ms: config.appointments_end_ms,
    location_id: config.location_id,
  }
}));

const config = $('Config | Orchestrator').first().json;
const calendarItems = $('Select | Admissions Calendars').all().map(item => item.json);
const calendarNames = new Map(
  calendarItems.map(item => [String(item.calendar_id), String(item.calendar_name ?? '')])
);

function clean(value) {
  if (value === null || value === undefined) return null;
  const text = String(value).trim();
  return text.length ? text : null;
}

function toIso(value) {
  if (value === null || value === undefined || value === '') return null;
  let normalized = value;
  if (typeof normalized === 'number' && normalized < 100000000000) normalized *= 1000;
  const date = new Date(normalized);
  return Number.isNaN(date.getTime()) ? null : date.toISOString();
}

function extractEvents(payload) {
  if (!payload) return [];
  if (Array.isArray(payload)) return payload.flatMap(extractEvents);
  if (Array.isArray(payload.events)) return payload.events;
  if (Array.isArray(payload.data?.events)) return payload.data.events;
  if (Array.isArray(payload.data)) return payload.data;
  return [];
}

function normalizeText(value) {
  return String(value ?? '')
    .toLocaleLowerCase('es')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function appointmentType(calendarId, calendarName, title) {
  if (String(calendarId ?? '') === String(config.pasadia_calendar_id ?? '')) {
    return 'trial_day';
  }

  const haystack = normalizeText(`${calendarName} ${title}`);

  if (
    haystack.includes('pasadia') ||
    haystack.includes('trial day')
  ) return 'trial_day';

  if (
    haystack.includes('school tour') ||
    haystack.includes('tour escolar') ||
    haystack.includes('visita escolar') ||
    haystack.includes('visita')
  ) return 'school_tour';

  return 'other';
}

const rawEvents = $input.all().flatMap(item => extractEvents(item.json));
const deduped = new Map();

for (const event of rawEvents) {
  const appointmentId = clean(event.id ?? event.eventId);
  const calendarId = clean(event.calendarId ?? event.calendar_id);
  const contactId = clean(event.contactId ?? event.contact_id);

  // Calendar block events and unrelated objects can come through this endpoint.
  // A real appointment should have a contact and an appointment status.
  const rawStatus = clean(
    event.appointmentStatus ??
    event.appointment_status ??
    event.status
  )?.toLowerCase();

  if (!appointmentId || !calendarId || !contactId || !rawStatus) continue;

  const calendarName = calendarNames.get(calendarId) ?? '';
  const title = clean(event.title) ?? '';
  const type = appointmentType(calendarId, calendarName, title);

  // We queried only likely admissions calendars, but fallback mode may query
  // all active calendars. Discard unrelated appointment types here.
  if (type === 'other') continue;

  deduped.set(appointmentId, {
    appointment_id: appointmentId,
    calendar_id: calendarId,
    calendar_name: calendarName,
    appointment_type: type,
    contact_id: contactId,
    appointment_status: rawStatus,
    start_time: toIso(event.startTime ?? event.start_time),
    end_time: toIso(event.endTime ?? event.end_time),
    assigned_user_id: clean(
      event.assignedUserId ??
      event.assigned_user_id
    ),
    title,
    date_added: toIso(event.dateAdded ?? event.date_added),
    date_updated: toIso(event.dateUpdated ?? event.date_updated),
    address: clean(event.address),
    notes: clean(event.notes),
    raw_payload: event
  });
}

const events = [...deduped.values()];

return [{
  json: {
    p_location_id: config.location_id,
    p_events: events,
    p_reconciled_at: new Date().toISOString(),
    raw_events_received: rawEvents.length,
    classified_appointments: events.length,
    school_tour_appointments: events.filter(e => e.appointment_type === 'school_tour').length,
    trial_day_appointments: events.filter(e => e.appointment_type === 'trial_day').length,
    selected_calendars: calendarItems.map(item => ({
      id: item.calendar_id,
      name: item.calendar_name,
      selection_mode: item.selection_mode,
    })),
  }
}];

const input = $input.first().json;
const expectedKey = '8l_mnmCazHTxcYdrz6wOJJnW2dPuugg9yKZOaN9KG1E';
const suppliedKey = String(input.query?.key ?? input.body?.key ?? '').trim();

if (!suppliedKey || suppliedKey !== expectedKey) {
  throw new Error('Dashboard refresh key inválida.');
}

return [{ json: { trigger: 'dashboard_v2', requested_at: new Date().toISOString() } }];
